<?php

declare(strict_types=1);

// Help texts of the System status tab (lib/help/system_status.php). Split out of
// help.php, which had grown past the 400-line module budget: the tab already had
// its own renderer, so its strings get their own module rather than an arbitrary
// cut through one catalog. Keys are reached as __t('help_system_status.<key>').

return [
    'k13_client_failure' => 'Missionsliste und Dashboard zeigen empfangene Client-Phasen-Fehler mit Anzahl und Links auf die betroffenen VMs. Ausbleibende Meldungen erzeugen keinen Fehler; eine neuere Abschlussmeldung derselben Phase hebt den Hinweis auf.',
    'host_heading' => 'Host und Backup',
    'host_p1' => 'Die Karte „Host und Backup“ fasst die Prüfungen des Docker-Hosts zusammen: letztes Backup, letzter nachgewiesener Restore-Test, letzte Prüfsummen-Prüfung, bei einem Befund die Backup-Verschlüsselung (kein Zertifikat hinterlegt oder letzter Lauf unverschlüsselt, gelb) und, nur solange das Portal HTTPS ausliefert, das Ablaufdatum des Zertifikats. Sie zeigt die schlechteste Zeile mit deren eigenem Wort, rot vor gelb vor grau vor grün. Fehlt für eine Zeile der Beleg, steht dort „Keine Daten“ (grau), und die Karte wird nicht grün. „Unbekannt“ (grau) zeigt nur die Zertifikatszeile, wenn ihr Ablaufdatum nicht lesbar ist.',
    'host_p3' => 'Ab wann eine Zeile gelb oder rot wird: Restore-Test gelb, wenn der letzte Beleg :drill_days Tage oder länger zurückliegt. Zertifikat gelb ab :cert_days Tagen Restlaufzeit, rot nach Ablauf. Prüfsummen rot bei jeder Abweichung. Backup gelb bei überfälligem Lauf oder knappem Speicherplatz, rot bei Fehlschlag.',
    'host_p2' => 'Jede Zeile nennt ihre Maßnahme: beim Backup den Link zur Backup-Einstellung, beim Restore-Test den Befehl auf dem Docker-Host, bei den Prüfsummen den Befehl, solange noch keine Prüfung gemeldet wurde, beim Zertifikat die HTTPS-Einstellung. Die Links erscheinen nur mit der Berechtigung für Systemeinstellungen. Sind die Prüfsummen rot, weichen Backupstände von ihrem Manifest ab, und die Zeile nennt sie: Verwenden Sie diese Backupstände nicht für einen Restore, erzeugen Sie ein neues Backup und starten Sie die Prüfung danach erneut. Der Bereich ändert die Ampel „Interne Dienste“ nicht.',
    'service_card_heading' => 'Bereitstellungsdienst',
    'service_card_p1' => 'Die Fazitzeile unter der Überschrift nennt für jeden Zustand, der nicht in Ordnung ist, den nächsten Schritt: bei „Nicht erreichbar“ den Neustart des Dienstes auf dem Portal-Server, bei „Wartet vor Neustart“ den nächsten Versuch der Aufsicht. Die Zeile „Bereitstellungsdienst (Portal)“ unter „Interne Dienste“ zeigt nur das Lebenszeichen und verweist hierher.',
    'service_card_p1_b' => 'Die Karte zeigt drei unabhängige Angaben: ob gerade gearbeitet wird, ob neue Aufträge angenommen werden und ob noch eine Klärung offen ist. Offene Klärungen nennen die vollständige Anzahl und verlinken eine begrenzte Fallliste in die jeweiligen Auftragsprotokolle; dort liegt die konkrete Maßnahme. Die Bedienknöpfe erscheinen nur mit der Berechtigung für Systemeinstellungen; die Erklärung bleibt für alle sichtbar.',
    'service_card_link' => 'Zustände und Aktionen des Bereitstellungsdienstes im Detail',
    'system_status_roles_heading' => 'Einstellungen, Zugangsdaten und Systemstatus',
    'system_status_roles_p1' => 'Einstellungen steuern globales Verhalten, Zugangsdaten speichern verschlüsselte Ansible- und ESXi-Konten, und der Systemstatus zeigt beobachtete Ergebnisse sowie berechtigte Diagnose- und Reparaturaktionen.',
    'system_status_single_site' => 'VirtuSphere bindet MECM über genau einen {mecm:site_code} an. Mehrere IP-Freigaben erlauben mehreren Netzwerkadressen den Zugriff auf dieselbe Machine-API; sie bilden kein Multi-MECM.',
    'system_status_signals_heading' => 'Ergebnisberichte und {mecm:site}-Zustand richtig lesen',
    'system_status_signal_heartbeat' => 'Ein aktueller Ergebnisbericht zeigt: Genau diese geplante Aufgabe ist auf dem MECM-Server gelaufen und hat ihr Ergebnis an das Portal gemeldet. Er sagt nichts über die anderen Aufgaben aus, jede meldet sich einzeln.',
    'system_status_signal_combination' => 'Die Integration (Datenfluss) und der {mecm:site}-Zustand von MECM sind getrennt: Der Datenfluss kann grün laufen, während MECM selbst eine Warnung meldet, und ein ausgefallener Sync bedeutet nicht, dass MECM kritisch ist. Beide Badges deshalb einzeln lesen. Beide nutzen dieselben Statuswörter (Abschnitt „Statuswörter“): Eine gelbe „Warnung“ am Datenfluss heißt Bericht überfällig oder Lauf mit offenen Punkten, am {mecm:site}-Zustand eine Warnung von MECM selbst. Meldet sich der Site-Health-Reporter nicht mehr, steht an seiner Zeile „Warnung“, der letzte {mecm:site}-Befund wird grau „Veraltet“.',
    'directory_heading' => 'Active Directory',
    'directory_p1' => 'Die Karte trennt die Zulassung eines Domänencontrollers für die aktuelle Konfigurationsrevision von seinem Betriebsbeleg. Sie zählt zugelassene, aktuell erfolgreiche, gestörte und veraltete Controller und zeigt den letzten Erfolg aus dem zugelassenen Pool. Ein abgelaufenes Zertifikat ist gestört, ein bald ablaufendes eine Warnung.',
    'directory_p1_b' => 'Die Zertifikatsdaten stammen aus dem letzten manuellen Test; zusätzlich liest das Portal sie höchstens einmal am Tag je Controller nach einem erfolgreichen Verzeichniskontakt (Anmeldung, Sitzungsprüfung oder Suche) neu. Ist das gespeicherte Ablaufdatum vorbei, gab es danach aber noch erfolgreiche Anmeldungen, hat der Controller ein erneuertes Zertifikat: Er erscheint dann als veraltet statt gestört, und ein Test speichert das neue Datum. Sichtbar ist die Karte nur mit der Berechtigung „Benutzerkonten verwalten“; Domänencontroller-Adressen sind interne Infrastruktur.',
    'directory_p2' => 'Fällt die Karte auf „Kritisch“, prüft „Benutzer → Active Directory“ zuerst das Suchkonto und den zuletzt gescheiterten Controller; das gefilterte Sicherheitsprotokoll zeigt die typisierte Ursache. Ist das Suchkonto abgewiesen, nennt die Zeile „Zustand“ den Grund, den das AD meldet: falsches Passwort, abgelaufenes Passwort, deaktiviertes oder gesperrtes Konto. Solange kein Controller einsatzbereit ist, bleibt die lokale Notfallanmeldung nutzbar.',
    'logs_heading' => 'Protokolle und Fehlersuche',
    'logs_p1' => 'Es gibt zwei Arten von Protokollen. Das Auftragsprotokoll (Link „Protokoll“ bei jedem Auftrag unter „Bereitstellung“) zeigt die Ausgabe des laufenden Ansible-Auftrags in Echtzeit; hier schaut man hin, wenn eine Bereitstellung fehlschlägt. Das Audit-Protokoll unter „Protokolle“ (nur Administratoren) hält dagegen fest, wer wann was im System geändert hat.',
    'logs_p2' => 'Das Audit-Protokoll ist in vier Bereiche unterteilt (Reiter oben), damit nicht alles in einer Tabelle landet: „Sicherheit“ (Anmeldung und Zugriff, Benutzer, Zugangsdaten, Active Directory, Abgewiesene Maschinenzugriffe), „Ressourcen“ (Missionen, VMs, Portgruppen, Betriebssysteme), „Bereitstellung“ (Aufträge, MECM-Integration) und „System und Integrationen“ (System, Einstellungen, Legacy-API). Innerhalb eines Bereichs lässt sich weiter volltextsuchen sowie nach IP und einzelner Kategorie filtern.',
    'logs_p2_b' => '„Ältere Einträge“ und „Neuere Einträge“ bewegen sich in stabilen Fenstern von :page_size Einträgen; Filter- oder Reiterwechsel beginnen wieder bei den neuesten Treffern. Ist eine gespeicherte Position durch Aufbewahrung verschwunden oder ungültig, führt die Seite ausdrücklich zu den neuesten Einträgen zurück und behauptet keine veraltete Seitenzahl.',
    'logs_p2_c' => 'Die Kategorie „MECM-Integration“ enthält bewusst nur wichtige Ereignisse: Ausfall und Wiederkehr einer überwachten Quelle, zurückgezogene Paketversionen, die noch VMs zugewiesen sind, Vorlagen, die einer neuen Paketversion gefolgt sind, und abgelehnte Sync-Läufe. Einzelne Lebenszeichen werden nicht protokolliert, sonst wäre das Protokoll binnen Stunden unlesbar.',
    'logs_p2b' => 'Der Bereich „Sicherheit“ hält fest, wer Zugang zum System hat und hatte: erfolgreiche und fehlgeschlagene Anmeldungen, automatische Konto- und IP-Sperren, Abmeldungen, abgelaufene Sitzungen, Passwortwechsel sowie abgewiesene Anfragen (fehlende Berechtigung oder ungültiges CSRF-Token). Änderungs-Einträge nennen die geänderten Felder mit altem und neuem Wert; Geheimnisse und Notizen erscheinen nur als „geändert“. Auch Datenabflüsse werden vermerkt: der JSON-Export einer Mission und die CSV-Listen-Exporte.',
    'logs_p2b_b' => 'Bereitstellungsaufträge protokollieren im Bereich „Bereitstellung“ neben dem Einreihen auch ihr Ergebnis samt Grund: erfolgreich, teilweise erfolgreich, fehlgeschlagen, Ausgang unbekannt oder abgebrochen.',
    'logs_export' => 'Jeder Reiter lässt sich mit den aktuellen Filtern als CSV herunterladen. Der Export beantwortet dieselbe Frage wie die Tabelle darüber, ignoriert aber deren aktuelle Cursorposition und liefert höchstens :limit Datenzeilen ab dem neuesten Treffer. Passen mehr Treffer, steht der Hinweis „erste :limit von N“ schon vor dem Download über der Tabelle, und die Antwort führt Gesamtzahl, Grenze und Kappung als eigene Kopfzeilen mit; die Datei selbst bekommt bewusst keine zusätzliche Hinweiszeile, weil eine solche Zeile von Tabellenprogrammen als Datensatz gelesen würde. Wer alles braucht, grenzt den Filter weiter ein.',
    'logs_export_b' => 'Der Download selbst wird protokolliert, allerdings ohne den Suchbegriff und ohne den IP-Filter: festgehalten werden nur Reiter, ausgegebene und gesamte Trefferzahl, die Grenze und ein nicht zurückrechenbarer Fingerabdruck des Filters, mit dem sich zwei Exporte derselben Auswahl zuordnen lassen.',
    'logs_p3' => 'Aufgeräumt wird automatisch durch den Wartungsdienst: Sicherheits-Protokolle (Anmeldung, Benutzer, Zugangsdaten, Active Directory, abgewiesene Maschinenzugriffe) werden :security_days Tage aufbewahrt, alle übrigen Portal-Protokolleinträge :other_days Tage, der Anmeldeversuchs-Zähler :attempt_days Tage, Client-Phasen-Meldungen :client_days Tage, zurückgezogene Pakete und Betriebssysteme, die derzeit keiner VM zugeordnet sind (Pakete zusätzlich nie umgehängt), :package_days Tage. Niemand muss Protokolle von Hand löschen.',
    'logs_p4' => 'Auch die Ausgabe der Bereitstellungsaufträge wird aufgeräumt, aber erst :log_days Tage nachdem der Auftrag beendet ist. Ein laufender Auftrag verliert nie Zeilen. Missionsaufträge bleiben mit Status und Fehlermeldung in der Liste; öffnet man ihr Protokoll später, steht dort ein Hinweis statt einer leeren Tabelle. Missionslose ESXi-Inventaraufträge werden nach :system_days Tagen ganz entfernt. Bis dahin verlinkt ihre Karte im Systemstatus den letzten beendeten Auftrag direkt; danach zeigt sie bei einem alten Fehler einen Aufbewahrungshinweis statt eines toten Links.',
    'logs_texts_heading' => 'Protokolltexte lesen',
    'logs_texts_p1' => 'Protokollzeilen mit Ereigniscode erscheinen in der Sprache der Ansicht: Auf Deutsch sehen Sie deutsche Sätze, auf Englisch englische. Die Suche, der CSV-Export und die Filter arbeiten mit dem gespeicherten englischen Text. Zeilen ohne Ereigniscode, also ältere Einträge, behalten ihren gespeicherten englischen Text. In deutschen Zeilen stehen Gründe, Zustände und Ergebnisse als deutsche Wörter; die englische Ansicht und die Suche zeigen dafür den gespeicherten Code. Eine Fehlermeldung des Hosts oder von Ansible zum Ende eines Bereitstellungsauftrags steht nicht im Satz, sondern aufklappbar unter „Technische Details“. Die häufigsten englischen Sätze bedeuten:',
    'logs_texts_mac' => '„MAC callback rejected for job id …: <Code>“: Der Ansible-Host hat die MAC-Adressen eines Bereitstellungsauftrags zurückgemeldet, und das Portal hat diese Rückmeldung abgewiesen. Der Code nennt den Grund; „conflict“ heißt, dass die Rückmeldung nicht zum aktuellen Stand des Auftrags passt. Die VM ändert sich dabei nicht. Maßnahme: das Auftragsprotokoll lesen.',
    'logs_texts_catalog' => '„Catalog sync rejected for …: payload would retire X of Y active entries (threshold Z%)“: Der Paket-Sync hat einen Lauf abgelehnt, weil er mehr Pakete auf einmal zurückziehen wollte, als die Schutzschwelle erlaubt. Maßnahme: zuerst die Katalogquelle auf dem MECM-Server prüfen (Ordner der {mecm:collections}, WMI-Abfrage). Ist der große Rückzug gewollt, die Schwelle nur vorübergehend anheben; siehe Einstellungen, Kataloge und Inventar.',
    'logs_texts_recovery' => '„documented external check for deploy job id …: <Code> (resolution N)“: Eine Person hat die Prüfung eines Auftrags außerhalb des Portals festgehalten. Der Code nennt das Ergebnis: „confirmed_applied“ heißt, die Änderung ist auf dem Ziel angekommen; „confirmed_not_applied“, sie ist nicht angekommen; „inconclusive“, das ist nicht abschließend feststellbar. Das Portal führt dadurch selbst keinen Schritt aus.',
    'logs_texts_touch' => '„VM access confirmation refused for job id …: <Code>“: Ein Bereitstellungsauftrag wollte eine VM auf ESXi lesen oder schalten, und das Portal hat den Zugriff nicht bestätigt, etwa weil der Auftrag nicht mehr läuft (job_not_active) oder die VM nicht zu ihm gehört (vm_not_in_scope). Der Auftrag bricht vor dem ESXi-Zugriff ab; das Auftragsprotokoll zeigt denselben Code.',
    'logs_texts_refused' => '„refused to release create unit …“ und „refused to switch the deploy process contract …“: Ein Schritt wurde nicht freigegeben. Hinter dem Doppelpunkt steht die eine Bedingung, an der es gescheitert ist; sie ist die nächste Aufgabe. Maßnahme: das Auftragsprotokoll öffnen.',
    'logs_texts_settings' => '„Settings > Machine API“ in einem Auftragshinweis meint den Reiter Machine-API unter Einstellungen.',
    'firstaid_heading' => 'Erste Schritte bei Fehlern',
    'firstaid_p1' => 'Egal was klemmt, die Reihenfolge ist immer dieselbe. So findet man in wenigen Minuten heraus, welche Komponente betroffen ist:',
    'firstaid_step1' => 'Systemstatus öffnen: Nennt die Kopfzeile einen Bereich, oder steht eine Quelle auf „Warnung“, „Kritisch“ oder „Nicht erreichbar“, der {mecm:site}-Zustand von MECM auf „Eingeschränkt“ oder „Kritisch“? Wenn ja, steht die passende Handlungsanweisung direkt daneben; die typischen Diagnosen weiter unten auf dieser Seite helfen zusätzlich.',
    'firstaid_step2' => 'Ist eine Bereitstellung fehlgeschlagen: unter „Bereitstellung“ beim betroffenen Auftrag auf „Protokoll“ klicken. Dort steht die komplette Ansible-Ausgabe mit der eigentlichen Fehlermeldung.',
    'firstaid_step3' => 'Hängt eine VM in der Windows-Installation (Stufe 4/5 oder 5/5): auf der Seite „VM bearbeiten“ den Abschnitt „Client-Phasen“ öffnen. Er zeigt, welcher Schritt zuletzt lief und ob einer fehlgeschlagen ist.',
    'firstaid_step4' => 'Reicht das nicht: Das Betriebshandbuch liegt im Projektordner auf dem Server (nicht im Portal erreichbar): docs/operations/mecm-integration.md. Es beschreibt die Log-Dateien auf dem MECM-Server und den Clients sowie die häufigsten Fälle Schritt für Schritt. Was die vier MECM-Aufgaben in welcher Reihenfolge tun, zeigen die Ablaufdiagramme in docs/operations/mecm-scheduled-tasks.md im selben Projektordner.',
    'firstaid_step4_b' => 'Meldet der Client-Installer einen ContentShare-Manifestfehler, beendet er den Lauf vor jeder MECM-Änderung. Freigabepfad, Leserechte und Inhalt anhand des Betriebshandbuchs korrigieren und erst dann erneut starten.',
    'system_status_heading' => 'Der Systemstatus im Überblick',
    'system_status_p1' => 'VirtuSphere funktioniert nur im Zusammenspiel mit Skripten, die auf dem MECM-Server laufen. Der Systemstatus ist die erste Anlaufstelle, wenn irgendetwas nicht ankommt: Er trennt Bereitstellungsdienst, MECM-Synchronisation, {mecm:site}-Zustand von MECM, Ansible-Volltest, ESXi-Inventar, Abweichungen, interne Dienste, Host und Backup sowie Active Directory. Zu einem problematischen Zustand steht direkt eine Handlungsempfehlung.',
    'system_status_p2' => 'Die Seite ist bewusst für alle angemeldeten Benutzer sichtbar, nicht nur für Administratoren. Die erste Diagnose braucht also keine Administratorrechte: Jeder kann nachsehen, ob eine Quelle oder der {mecm:site}-Zustand von MECM auf „Kritisch“ steht, bevor er ein Problem meldet.',
    'system_status_p3' => 'Die Seite ist eine Momentaufnahme des Ladezeitpunkts und aktualisiert sich nicht von selbst. „Stand der Anzeige“ nennt diesen Zeitpunkt, „Status aktualisieren“ holt einen neuen. Ein offenes Fenster wird also nicht grün, wenn das Problem behoben ist.',
    'system_status_sources_heading' => 'Was wird überwacht?',
    'system_status_source_1' => 'MECM Device-Sync. Geplante Aufgabe „VirtuSphere MECM Devices Sync“, Skript mecm_new-device-sync.ps1. Sie fragt das Portal nach VMs, deren MAC-Adresse bekannt ist, legt sie als Geräte in MECM an und ordnet sie den {mecm:collections} ihres Betriebssystems, ihrer Pakete und ihrer Mission zu; eigene Zuordnungen, die nicht mehr gelten, entfernt sie wieder. Läuft die Aufgabe nicht, bleibt jede neue VM auf Stufe 3/5 stehen: die MAC ist gemeldet, aber MECM lernt sie nie kennen.',
    'system_status_source_2' => 'MECM Paket-Sync. Geplante Aufgabe „VirtuSphere MECM Packages Sync“, Skript mecm_Packages-TaskSeq-sync.ps1. Sie liest die {mecm:collections} im Ordner VirtuSphere_Applications und die {mecm:task_sequences} aus MECM aus und meldet sie an das Portal. Daraus entstehen die Seiten „Pakete“ und „Betriebssysteme“. Läuft die Aufgabe nicht, veraltet die Auswahl still: neue Pakete fehlen, zurückgezogene bleiben stehen.',
    'system_status_source_3' => 'MECM Paket-Import (Autoimporter). Geplante Aufgabe „VirtuSphere MECM Package Import“, Skript mecm_autoimporter.ps1. Sie sieht im Paketordner auf dem MECM-Server nach und baut aus jedem neuen Unterordner mit config.json automatisch eine MECM-{mecm:application}, mit generateOwnDeviceColletion auch {mecm:collection} und {mecm:deployment}.',
    'system_status_source_3_b' => 'Ohne generateOwnDeviceColletion entsteht keine {mecm:collection}; das Paket erscheint dann nicht im Portal. Läuft die Aufgabe nicht, bleiben abgelegte Pakete einfach liegen; sie erscheinen weder in MECM noch im Portal. Offene Punkte merkt sich der Autoimporter: Auch ein Lauf ohne neue Dateien meldet sie als Warnung und prüft die betroffenen Pakete mit Abstand erneut.',
    'system_status_source_4' => 'MECM Site-Health: der offizielle, von MECM gemeldete {mecm:site}-Zustand in den Wörtern des fachlichen Zustands: „OK“, „Warnung“, „Eingeschränkt“, „Kritisch“ oder „Unbekannt“. Ein eigener SYSTEM-Task auf dem MECM-Server fragt SMS_SummarizerSiteStatus ab und zählt bei Warnung oder kritisch zusätzlich, welche Rollen der {mecm:site}-Systeme und welche Komponenten MECM so bewertet, nur nach Typ und ohne Servernamen.',
    'system_status_source_4_b' => 'Das Portal ordnet jeden Typ als Kernteil oder unterstützend ein: Sind nur unterstützende Teile kritisch (zum Beispiel {mecm:distribution_points}, Erkennung, Dienstverbindungspunkt), heißt der Zustand „Eingeschränkt“ (gelb). Ist ein Kernteil ({mecm:site_server}, SQL, {mecm:sms_provider}, Verwaltungspunkt, Verteilungs- und Paketübertragungs-Manager, SMS_EXECUTIVE und ähnliche) oder ein nicht eingeordneter Typ kritisch, oder fehlen Einzelheiten, gilt das MECM-Urteil „Kritisch“ (rot). Ein überfälliger Reporter erscheint gelb als „Warnung“. Der letzte {mecm:site}-Befund bleibt sichtbar, wird aber grau als „Veraltet“ und historisch gekennzeichnet; daraus folgt kein aktueller kritischer MECM-Zustand.',
    'system_status_source_5' => 'Wartungsdienst (Portal). Keine geplante Aufgabe auf dem MECM-Server, sondern ein eigener Container auf dem Portal-Server, der dauerhaft mitläuft. Er erledigt die Aufräumarbeiten und die ESXi-Inventarplanung und meldet sich dabei selbst; sein Takt steht in der Zeile unter „Intervall“. Steht er, bleiben diese Aufräum- und Planungsarbeiten liegen, die MECM-Aufgaben laufen davon unberührt weiter.',
    'system_status_status_heading' => 'Die Statusanzeige lesen',
    'system_status_status_p1' => 'Die MECM-Quellen sind PowerShell-Skripte, die auf dem MECM-Server in der Windows-Aufgabenplanung als geplante Aufgaben laufen. Nach jedem Durchlauf schicken sie eine kurze Meldung an das Portal, das Lebenszeichen. Das Portal fragt also nichts ab, es wartet nur. Kommt länger keine Meldung als erwartet, wechselt der Status; die Fristen stehen bei den Zuständen darunter. Jeder Zustand wird mit Text und Farbe angezeigt:',
    'system_status_status_p2' => 'Jede Zeile zeigt dieselben Felder in derselben Reihenfolge, auch wenn eine Quelle eines davon nie gemeldet hat. Ein Strich statt eines Werts bedeutet deshalb genau eines: zu diesem Feld ist nichts gespeichert. Er sagt nicht, dass das Ereignis nie eingetreten ist; eine Aufgabe, die noch nie fehlgeschlagen ist, und eine, deren Fehlerzeitpunkt nie ankam, sehen hier gleich aus. Eine Zeile aus einem alten Skript hat keinen Erfolgszeitpunkt, sondern nur ihre letzte Meldung; sie steht an derselben Stelle unter einem anderen Namen.',
    // Der Aufklappblock unter den Zählern. Vorher sendeten Device-Sync und
    // Autoimporter dort nichts, also nannte „Datenwarnungen: 3" keine einzige VM.
    'system_status_status_verdict' => 'Jede Karte beginnt mit einer Fazitzeile, die sagt, ob Sie etwas tun müssen: „Kein Eingriff nötig.“, „Handlung nötig.“ mit dem nächsten Schritt oder „Kein aktueller Beleg.“. Sie liest denselben Zustand wie die Karte im Überblick. Zeiten stehen relativ und absolut, etwa „vor wenigen Minuten (Datum und Uhrzeit)“; „vor“ bezieht sich auf den Stand der Anzeige im Seitenkopf. Dauern stehen in höchstens zwei Einheiten.',
    'system_status_status_verdict_b' => 'Läuft gerade ein Lauf, steht eine eigene Zeile „Läuft seit …“ mit der Dauer des letzten Laufs; das Ergebnis darunter bleibt das des letzten abgeschlossenen Laufs. Ein gemeldeter Start ist kein direkter Beleg, dass der Prozess noch arbeitet; erst wenn der Lauf seine Frist überschreitet, erscheint der Hinweis, das Tageslog zu prüfen. Beim Autoimporter nennt die Fazitzeile Scan und Verteilung getrennt: Verteilhinweise an {mecm:distribution_points} (DP) sind nicht Teil des Scanergebnisses und blockieren nichts. „Lauf ohne Änderung: Ja“ heißt, der Lauf fand keine geänderte Datei und nichts Fälliges.',
    'system_status_status_p3' => 'Zählt eine Zeile Datenwarnungen oder Fehler, steht unter „Technische Details“ eine Ursachenzeile: je Fall ein kurzer Code, dahinter „target=“ mit dem VM-, Paket- oder Ordnernamen und, wenn es um eine Zuweisung geht, „collection=“ mit der {mecm:collection}. Also etwa „collection_missing target=WEB01 collection=Firefox-115.0“. Passt nicht jeder Fall in den Bericht, zählt die Zeile den Rest als „(+N weitere)“.',
    'system_status_status_p3_b' => 'Beim Autoimporter zerlegt das Portal die Zeile in eine Tabelle: je Ursache der Klartext mit Code, die Anzahl und eine aufklappbare Paketliste, Probleme vor laufender Verteilung; ein Code, den das Portal nicht kennt, steht roh als „Unbekannter Code“. Die Hinweise auf der Karte nennen die Anzahl der Pakete, mit Rest „mindestens“. Die unveränderte Zeile bleibt unter „Rohdaten“ mit einem Kopieren-Knopf für Rückfragen. Die Liste unten erklärt die Codes.',
    'system_status_status_code_membership_operation_uncertain' => 'Eine begonnene MECM-Mitgliedschaft ist nicht sicher als eigene Operation des Device-Sync belegt. Der nächste Lauf liest die tatsächliche Mitgliedschaft und klärt den Eintrag selbst; die VM bleibt nur blockiert, solange diese Mitgliedschaft nicht lesbar ist. Maßnahme: nur bei anhaltender Blockade das Tageslog des Device-Sync lesen (Zeile „Journaleintrag“) und in der MECM-Konsole prüfen, ob die Zuordnung der VM zur {mecm:collection} tatsächlich gesetzt ist.',
    'system_status_status_code_package_content_in_progress' => 'Hinweis, kein offener Punkt: MECM verteilt den Inhalt noch an die {mecm:distribution_points}. Maßnahme: keine. Geräte können das Paket nutzen, sobald ihr DP den Inhalt anbietet; {mecm:deployment} und Zuweisung bestehen bereits.',
    'system_status_status_code_package_content_unknown' => 'Die {mecm:application} oder ihr {mecm:deployment_type} ist nicht eindeutig lesbar, oder ohne lesbaren Verteilstand ist unklar, ob eine Erst- oder Updateverteilung nötig ist. In diesem Lauf wird kein Contentauftrag gestellt; die {mecm:collection} und die {mecm:deployments} werden trotzdem abgeglichen. Der Autoimporter versucht es nach dem Takt erneut und danach mit wachsendem Abstand bis zu einer Stunde. Maßnahme: Autoimporter-Tageslog lesen.',
    'system_status_status_code_package_content_request_failed' => 'Der Contentauftrag war nicht möglich: DP-Gruppe nicht konfiguriert, oder MECM hat die Verteilung nicht angenommen. Die {mecm:collection} und die {mecm:deployments} werden trotzdem abgeglichen. Der Autoimporter wiederholt den Auftrag nur, solange MECM ihn nicht angenommen hat. Maßnahme: Ursache im Autoimporter-Tageslog prüfen.',
    'system_status_status_code_package_content_failed' => 'Hinweis, kein offener Punkt: Mindestens ein {mecm:distribution_point} meldet einen Verteilfehler, etwa weil er offline ist. Nichts wird blockiert, MECM verteilt weiter. Maßnahme: nur bei Bedarf in der MECM-Konsole unter {mecm:path_content_status} den DP prüfen.',
    'system_status_status_code_package_content_group_empty' => 'Die DP-Gruppe der Erstverteilung hat keine Mitglieder, deshalb hat der Inhalt kein Ziel. Maßnahme: einen {mecm:distribution_point} in die Gruppe aufnehmen. Danach fordert der Autoimporter die Erstverteilung an; das Tageslog nennt die Gruppe.',
    'system_status_status_code_package_definition_drift' => 'Die MECM-{mecm:application} oder ihr {mecm:deployment_type} weicht von der erwarteten Definition ab oder ist mehrdeutig, oder eine namensgleich neu angelegte {mecm:application} gehört nicht zu VirtuSphere (ohne Marker und außerhalb des Ordners VirtuSphere_Applications). Der Autoimporter übernimmt und überschreibt sie nicht. Maßnahme: Definition und Tageslog prüfen.',
    'system_status_status_code_package_folder_failed' => 'Die {mecm:application} konnte nach dem Anlegen nicht in den Ordner VirtuSphere_Applications verschoben werden. Das betrifft nur die Ordnerablage: Der Paketkatalog im Portal liest den Ordner der {mecm:collections}, und die {mecm:application} bleibt nutzbar. Der Autoimporter versucht das Verschieben nach dem Takt erneut und danach mit wachsendem Abstand bis zu einer Stunde. Maßnahme: Bleibt er erfolglos, die Ursache im Tageslog prüfen.',
    'system_status_status_code_package_cleanup_failed' => 'Die mit removeOldVersion angeforderte automatische Entfernung alter Versionen ist noch gesperrt oder bei einer Einheit gescheitert; freie Versionen, fehlendes Eigentum, Referenzen oder ein unbelegter Ersatz sind mögliche Gründe. Maßnahme: Zielstand, Eigentum, Referenzen und die {mecm:deployments} der neuen Version im Autoimporter-Tageslog prüfen.',
    'system_status_status_code_package_config_invalid' => 'Die config.json eines Paketordners ist unlesbar, unvollständig oder verletzt die erlaubten Werte (siehe „Erlaubte Werte“ unter dieser Liste). Der Ordner wird übersprungen. Maßnahme: config.json des unter „target=“ genannten Ordners korrigieren; der nächste Scan nach der Änderung importiert ihn.',
    'system_status_status_code_package_source_missing' => 'Der Ordner files der Paketfreigabe fehlt oder ist nicht erreichbar. Der Autoimporter importiert nichts und meldet das bei jedem Lauf. Maßnahme: Freigabe und Leserechte des Kontos prüfen, unter dem der Autoimporter läuft; „target=“ nennt den Pfad.',
    'system_status_status_code_package_template_failed' => 'Der Vorlagensatz aus Package_Vorlage ließ sich nicht in den Paketordner übernehmen oder bestand den SHA-256-Vergleich nicht. Für dieses Paket ändert der Autoimporter in MECM nichts, bis die Übernahme gelingt. Der Autoimporter versucht es nach dem Takt erneut und danach mit wachsendem Abstand bis zu einer Stunde. Maßnahme: Package_Vorlage und die Schreibrechte auf den Paketordner prüfen; das Tageslog nennt die Ursache.',
    'system_status_status_code_package_deploy_failed' => '{mecm:Deployments} ließen sich nicht anlegen: mit dem Zweck „Erforderlich“ auf die {mecm:collection} des Pakets oder, mit „collection=“, mit dem Zweck „Verfügbar“ auf die {mecm:collection} aus DeployTo. Die {mecm:collection} gibt es, MECM hat das Anlegen abgelehnt. Der Autoimporter versucht es nach dem Takt erneut und danach mit wachsendem Abstand bis zu einer Stunde. Maßnahme: die Ursache im Tageslog lesen.',
    'system_status_status_code_package_deployto_missing' => 'Die in DeployTo genannte {mecm:collection} für Geräte oder Benutzer existiert in MECM nicht, deshalb gibt es keine {mecm:deployments} mit dem Zweck „Verfügbar“. Der Lauf merkt sich das Paket und prüft es stündlich erneut, ohne jede Minute neu zu scannen. Maßnahme: {mecm:collection} mit genau diesem Namen anlegen oder DeployTo in der config.json korrigieren; danach die config.json speichern, damit der nächste Lauf sofort prüft.',
    'system_status_status_code_package_deployto_ambiguous' => 'In MECM gibt es mehrere {mecm:collections} mit dem Namen aus DeployTo, auch je eine {mecm:collection} für Geräte und für Benutzer gleichen Namens zählen. Der Autoimporter rät nicht. Maßnahme: eine der {mecm:collections} umbenennen.',
    'system_status_status_code_package_deployto_invalid' => 'DeployTo nennt die {mecm:collection}, die der Autoimporter für das Paket selbst anlegt. Für sie gibt es schon {mecm:deployments} mit dem Zweck „Erforderlich“, zusätzliche mit „Verfügbar“ gibt es nicht. Maßnahme: DeployTo leeren oder eine andere {mecm:collection} nennen.',
    'system_status_status_code_package_scan_failed' => 'Ein unerwarteter MECM-Fehler beendete die Bearbeitung dieses Pakets, MECM war aber erreichbar. Die übrigen Pakete liefen weiter. Der Autoimporter versucht das Paket nach dem Takt erneut und danach mit wachsendem Abstand bis zu einer Stunde. Maßnahme: Fehler im Tageslog lesen; bleibt er, das Paket in der MECM-Konsole prüfen.',
    'system_status_status_counters' => 'Die Zähler selbst beziehen sich immer nur auf den letzten belegten Abschluss: Ein Lebenszeichen einer alten Skriptversion verwirft dessen Zuordnung, statt mit alten Zählern einen neuen Erfolg zu behaupten. Die Verteilung an die {mecm:distribution_points} übernimmt MECM. Der Autoimporter fordert je neuem Quellstand höchstens einen Auftrag an, unabhängig vom DP-Stand; unveränderte Quellen lösen keinen erneuten Auftrag aus. Die {mecm:collection} und die {mecm:deployments} zieht er immer nach, auch wenn noch kein DP erfolgreich ist, ein DP offline ist oder ersetzt wurde. Verteilhinweise sind keine offenen Punkte und färben das Scanergebnis nicht gelb. Die Zuweisung bleibt bestehen; Geräte können das Paket verwenden, sobald der ihnen zugeordnete DP den Inhalt anbietet.',
    'system_status_status_counters_b' => 'Eine Versionsänderung erzeugt einen neuen Namen der {mecm:application}. Parallel gelieferte Quellen sind keine Altobjekte; numerisch gleiche Versionen wie 1 und 1.0 erlauben keinen eindeutigen Bereinigungsplan. Abschluss offen bezeichnet eine Startmeldung ohne Abschluss. Der Autoimporter-Laufzustand bleibt neutral und beschreibt nur die empfangene Laufmeldung, keinen direkt geprüften Prozesszustand. Ein Scan, der deutlich länger dauert als der letzte abgeschlossene, kann die Meldefrist überschreiten.',
    'system_status_status_counters_c' => 'Die Autoimporter-Karte trennt Laufzustand, letztes Scanergebnis und Verteilung. Verteilhinweise stammen aus dem letzten Scan und werden höchstens alle :minutes Minuten aufgefrischt; den genauen Stand je DP zeigt die MECM-Konsole.',
    'system_status_status_cleanup_p4' => 'removeOldVersion=true ist die maßgebliche Anforderung zur automatischen Entfernung ersetzter Altversionen. Sobald MECM den Contentauftrag der neuen Version angenommen und die Verteilung begonnen hat und die {mecm:deployments} der neuen Version geprüft sind, erhebt und revalidiert der Autoimporter den Cleanup-Plan und entfernt alte {mecm:deployments}, {mecm:applications} und {mecm:collections}. Der DP-Stand spielt dafür keine Rolle, auch null erfolgreiche DPs sind zulässig. Parallele Quellversionen, fremde Objekte, Referenzen und ein nicht angenommener Auftrag sperren die Entfernung und ergeben package_cleanup_failed.',
    'system_status_status_package_p5' => 'Nennt „Technische Details“ eine unbekannte Funktion wie Get-VsPackageRetainedNames, läuft ein gemischter MECM-Server-Dateisatz. Das ist kein DP-Fehler. Keine einzelne Common- oder Autoimporter-Datei nachkopieren: den vollständigen neuen Powershell-MECM-Ordner auf dem MECM-Server bereitstellen und daraus install-VirtuSphere-MECM.ps1 -Upgrade -ServerOnly als Administrator ausführen.',
    'system_status_status_package_p5_b' => 'Der Installer prüft den gemeinsamen Vertrag vor und nach dem atomaren Austausch; der Autoimporter verweigert einen unpassenden Common-Stand sofort. Derzeit ist nur dieses reine Serverupdate freigegeben: Es tauscht Serverskripte und Aufgaben und lässt die Paketvorlage unverändert. Ein volles Update ist noch gesperrt; der Installer bricht es vor jeder Änderung ab.',
    // Geschlossene Codes, die der Device-Sync in seiner
    // Ursachenzeile schreiben kann, wenn er ein Geraet nicht zuordnen kann. Jeder
    // nennt genau eine Massnahme; ohne diese Zuordnung ist der Code fuer den
    // Operator nur ein Wort.
    'system_status_identity_heading' => 'Wenn der Device-Sync eine VM nicht zuordnen kann',
    'system_status_identity_p1' => 'Meldet die Zeile „MECM Device-Sync“ Fehler, nennt die Ursachenzeile unter „Technische Details“ den Grund als kurzen Code. Diese Codes betreffen die Identität eines Geräts. Sie bedeuten immer: Es wurde nichts geändert, und die VM bleibt in der Warteschlange, bis der genannte Schritt erledigt ist. Außer bei stale_rollout_revision prüft der Device-Sync eine so gesperrte VM erst nach einer Änderung an ihr im Portal oder nach seinem festen Wiederholungstakt erneut; eine Korrektur allein in MECM wirkt deshalb erst nach einigen Minuten.',
    'system_status_identity_1' => 'device_name_invalid: Der Windows-Hostname der VM taugt nicht als Rolloutname in MECM. Im VM-Editor korrigieren: höchstens :max Zeichen, nur Buchstaben, Ziffern und innenliegende Bindestriche, kein Punkt.',
    'system_status_identity_2' => 'previous_resource_present: Das Gerät des vorherigen Rollouts existiert in MECM noch. In der MECM-Konsole löschen; der Device-Sync importiert den neuen Namen danach von selbst, sobald er die VM wieder prüft. Ein ungeklärter Journaleintrag der VM klärt sich dabei ebenfalls von selbst.',
    'system_status_identity_3' => 'resource_id_missing: Die gebundene ResourceID gibt es in MECM nicht mehr, das Gerät wurde dort also gelöscht. „MECM-ID zurücksetzen“ ausführen, damit die VM neu importiert wird.',
    'system_status_identity_4' => 'resource_mac_conflict: Das gebundene Gerät trägt in MECM keine der MACs, die die VM im Portal hat. Vor jedem Löschen in der MECM-Konsole die MACs des Geräts mit allen Karten der VM im Portal vergleichen. Zeigt MECM eine MAC dieser VM, ist das Gerät die lebende Maschine und kein Altgerät: nicht löschen und nicht zurücksetzen, sondern die MECM-Serverskripte aktualisieren. Ältere Versionen erkennen ein Gerät mit zwei Karten nicht, vor device-sync/2.1 auch keine andere Karte als die DHCP-Karte. Trägt das Gerät nur fremde MACs, wurde meist die VM neu angelegt und das Gerät ist die alte Maschine; dann das alte Gerät in MECM löschen und zurücksetzen. Bis dahin bleibt diese VM in der Warteschlange; die übrigen VMs werden weiter abgeglichen.',
    'system_status_identity_5' => 'mac_conflict: Name und MAC zeigen auf verschiedene MECM-Geräte, oder eines von beiden gehört einem fremden Gerät. Vor jedem Löschen in der MECM-Konsole die MACs des gleichnamigen Geräts mit den Karten der VM im Portal vergleichen. Trägt es die MAC der Karte auf der WDS-Portgruppe, gehört es zu dieser VM: nichts löschen, sondern die MECM-Serverskripte aktualisieren; ältere Versionen erkennen ein Gerät mit zwei Karten nicht. Sonst von Hand entscheiden, welcher Datensatz gilt, und den anderen in MECM entfernen.',
    'system_status_identity_6' => 'device_identity_ambiguous: Mehrere MECM-Datensätze passen auf denselben Namen, dieselbe MAC oder dieselbe ResourceID. Die Dubletten in der MECM-Konsole auflösen; das Skript wählt bewusst keinen davon aus.',
    'system_status_identity_7' => 'stale_rollout_revision: Der Scan hat mit einem veralteten Stand gearbeitet, weil zwischendurch zurückgesetzt wurde. Hier ist nichts zu tun, der nächste Scan läuft mit dem aktuellen Stand durch.',
    'system_status_identity_8' => 'pxe_nic_ambiguous: Mehr als eine Netzwerkkarte der VM liegt auf der WDS-Portgruppe der Mission, deshalb ist nicht eindeutig, welche MAC MECM für PXE bekommen soll. Im VM-Editor genau eine Karte auf der WDS-Portgruppe lassen.',
    'system_status_cause_group_p1' => 'Weitere Gründe, die der Device-Sync an einer VM melden kann, mit dem Kurztext wie an der VM:',
    'system_status_cause_group_action' => 'Maßnahme bei diesen Codes: Bei „VM ohne Mission“ hat das Portal zur VM keinen Missionsnamen geliefert; prüfen Sie im Portal, ob ihre Mission noch besteht. Sonst lesen Sie das Tageslog des Device-Sync (die Zeile nennt den Code und „target=“) und prüfen in der MECM-Konsole, ob die {mecm:collection} der VM existiert, eindeutig ist und die Zuordnung gesetzt ist. Scheitert die Meldung ans Portal, prüfen Sie zusätzlich, ob die Machine-API vom MECM-Server erreichbar und seine IP freigegeben ist. Nachgemeldete Zuordnungen, eine noch fehlende ResourceID und ein ungeklärter Journaleintrag klären sich im nächsten Lauf selbst, sobald die Mitgliedschaften lesbar sind.',
    'system_status_identity_9' => 'mac_missing: Keine Netzwerkkarte der VM liegt auf der WDS-Portgruppe der Mission, oder ihre MAC fehlt noch. Die MAC entsteht erst mit dem MAC-Export; die Portgruppe muss genau so heißen wie in der Mission, auch in Groß- und Kleinschreibung.',
    // MX1: Der Grund je VM kommt zusätzlich über reportDeviceCauses und steht an der VM.
    'system_status_identity_p2' => 'Außer dieser Übersicht meldet der Device-Sync den Grund auch je VM. Das Portal zeigt ihn an der VM selbst, am Befund „Wartet auf MECM“ in VM-Liste, VM-Übersicht und VM-Editor, und nur für die aktuelle Rollout-Revision der VM; nach „MECM-ID zurücksetzen“ gilt erst die nächste Meldung. Ein Grund, den kein Lauf erneut meldet, verfällt nach :days Tagen. Das wirkt erst, wenn die MECM-Serverskripte desselben Release installiert sind.',
    'system_status_work_heading' => 'Mit den Status-Hinweisen arbeiten',
    'system_status_work_0' => 'Hat sich noch nie eine der Aufgaben Devices Sync, Packages Sync, Package Import oder Site Health gemeldet, ist MECM entweder noch nicht angebunden, oder die Aufgaben laufen, werden aber an den IP-Freigaben der Machine-API abgewiesen; dann nennt ein Hinweis die IP, die mit der Rolle „MECM-Server“ freigegeben werden muss. Dann stehen keine Hinweistexte an den Zeilen, denn dort ist nichts zu reparieren, was es noch nicht gibt; stattdessen nennt der Abschnitt einmal den nächsten Schritt.',
    'system_status_work_1' => 'Bei „Warnung“, „Kritisch“ oder „Nicht erreichbar“ (MECM-{mecm:site}: „Eingeschränkt“ oder „Kritisch“) zuerst den Hinweistext direkt neben der Zeile lesen. Er nennt in Klartext die wahrscheinlichste Ursache und den nächsten Schritt; niemand muss die Bedeutung der Quellen auswendig kennen.',
    'system_status_work_2' => 'Den Schritt ausführen oder gezielt weitergeben: Manche Maßnahmen (geplante Aufgaben auf dem MECM-Server starten, Einstellungen ändern) brauchen Administrator- oder Serverzugriff. Dann der zuständigen Person die betroffene Zeile samt Hinweistext melden; das erspart ihr die halbe Diagnose.',
    'system_status_work_3' => 'Nach der Behebung kurz warten: Jede Quelle meldet sich in ihrem festen Takt (Angabe „Intervall“ in der Zeile). Die Zeile springt erst mit dem nächsten Lebenszeichen wieder auf „OK“ (bei den internen Diensten „Aktuell“), nicht sofort nach dem Eingriff. Mit diesem Wechsel verschwindet auch der Hinweistext, denn er ist eine Reparaturanweisung und keine Beschreibung.',
    'system_status_work_4' => 'Bleibt die Zeile trotzdem auf „Kritisch“ (MECM-{mecm:site}: „Kritisch“): mit den typischen Diagnosen weiter unten fortfahren und danach das Betriebshandbuch im Projektordner auf dem Server (nicht im Portal erreichbar) heranziehen: docs/operations/mecm-integration.md.',
    'system_status_fix_heading' => 'Typische Diagnosen',
    'system_status_fix_1' => 'Sync-Quellen auf „Kritisch“, aber „MECM-{mecm:site}“ auf „OK“ (grün): MECM selbst läuft, nur die geplanten Aufgaben melden sich nicht. Zuerst das Setup-Tageslog unter %ProgramFiles%\\VirtuSphere\\Logs prüfen. Meldet es einen unvollständigen Installer-Rollback, keinen Task manuell starten, sondern die dort genannte Abweichung beheben und den Installer erneut ausführen; freigegeben ist derzeit nur das reine Serverupdate (-Upgrade -ServerOnly), ein volles Update bricht vor jeder Änderung ab. Andernfalls auf dem MECM-Server die Aufgabenplanung öffnen und die Aufgaben „VirtuSphere MECM Devices Sync“, „VirtuSphere MECM Packages Sync“ bzw. „VirtuSphere MECM Package Import“ starten.',
    'system_status_fix_2' => 'MECM-{mecm:site} auf „Kritisch“ (rot) oder „Eingeschränkt“ (gelb): MECM selbst meldet für den exakt gespeicherten {mecm:site_code} den Zustand 2. Die Tabelle auf der Karte „MECM-{mecm:site_status}“ nennt die betroffenen Rollen und Komponenten mit ihrer Einordnung; Details in der MECM-Konsole unter {mecm:path_component_status} prüfen.',
    'system_status_fix_2_b' => 'MECM bewertet eine Komponente nach der Zahl ihrer Fehlermeldungen seit Mitternacht: in der Standardeinstellung ab einer Fehlermeldung Warnung, ab fünf kritisch. Um Mitternacht setzt MECM die Zähler zurück. Nicht erreichbare {mecm:distribution_points} erzeugen solche Fehler auch beim Verteilungs-Manager. Der Weg zu Grün führt deshalb über die {mecm:distribution_points}: wieder erreichbar machen oder aus MECM entfernen; der Zustand erholt sich spätestens nach dem nächsten Zurücksetzen. Ein fehlender {mecm:site_code}, mehrere oder unlesbare Treffer und ein Fehler des {mecm:sms_provider}s bleiben grau und bedeuten nicht, dass MECM kritisch ist.',
    'system_status_fix_3' => '„Wartungsdienst“ auf „Nicht erreichbar“: Der interne Dienst des Portals steht. Auf dem Portal-Server (Ubuntu) im Projektverzeichnis „docker compose ps“ prüfen und mit „docker compose up -d maintenance-worker“ neu starten. „Wartungsdienst“ auf „Beeinträchtigt“ (siehe Legende): Der Dienst läuft, aber einzelne Teilaufgaben seines Durchlaufs scheitern; die Zeile nennt sie. Die Ursache steht in „docker compose logs maintenance-worker“; ein Neustart behebt sie nicht.',
    'system_status_fix_4' => 'Für tiefergehende Fälle (Logdateien auf dem MECM-Server, Sonderfälle der Skripte) gibt es das Betriebshandbuch im Projektordner auf dem Server (nicht im Portal erreichbar): docs/operations/mecm-integration.md. Die Abläufe der vier Aufgaben zeigt docs/operations/mecm-scheduled-tasks.md im selben Projektordner, welche Prüfung hinter jeder Karte dieser Seite steht, docs/operations/system-status-checks.md.',
    'mecmfolders_heading' => 'Ordnerstruktur in der MECM-Konsole: was liegt wo?',
    'mecmfolders_p1' => 'Alle von VirtuSphere erzeugten Objekte liegen in drei fest benannten Ordnern der MECM-Konsole. So bleiben sie sauber von manuell gepflegten MECM-Objekten getrennt, und neues Personal findet sich sofort zurecht:',
    'mecmfolders_item1' => 'VirtuSphere_OS (unter {mecm:path_device_collections}): je {mecm:task_sequence} eine gleichnamige {mecm:collection}. Über sie erhalten VMs ihr Betriebssystem; angelegt vom Device-Sync.',
    'mecmfolders_item2' => 'VirtuSphere_Missions (ebenfalls unter {mecm:path_device_collections}): je Mission eine {mecm:collection} mit exakt dem Missionsnamen aus dem Portal; angelegt vom Device-Sync.',
    'mecmfolders_item3' => 'VirtuSphere_Applications: gibt es zweimal, einmal unter {mecm:path_device_collections} (je Paket mit generateOwnDeviceColletion eine {mecm:collection} „Name-Version“) und einmal unter {mecm:path_applications} (die {mecm:applications} selbst); befüllt vom Autoimporter. Wichtig: Der Paket-Sync liest genau diesen Ordner der {mecm:collections} als Katalogquelle. Nur {mecm:collections} in diesem Ordner erscheinen im Portal als Pakete.',
    'mecmfolders_p2' => 'Alle drei Ordner legen die Skripte bei Bedarf selbst an, niemand muss sie von Hand anlegen (Voraussetzung: MECM-Konsole ab Version 2111; auf älteren Ständen die Ordner einmalig manuell anlegen). Die Geräte selbst landen ohne eigenen Ordner in „All Systems“ und werden den {mecm:collections} nur zugeordnet.',
    'mecmfolders_p3' => 'Für den Alltag heißt das: Ein Paket, dessen {mecm:collection} außerhalb von VirtuSphere_Applications liegt, taucht nicht im Portal auf; nach dem Verschieben in den Ordner schon. Benennen Sie die Ordner und ihre Inhalte nicht um, denn die Namen sind die Verbindung zwischen Portal und MECM.',
    'clientphases_heading' => 'Client-Phasen: die Windows-Installation im Blick',
    'clientphases_p1' => 'Ab Stufe 4/5 arbeitet nicht mehr das Portal, sondern die VM selbst: Sie bootet per PXE, installiert Windows, und kleine Skripte auf dem frisch installierten System melden ihren Fortschritt zurück. Auf der Seite „VM bearbeiten“ zeigt der Abschnitt „Client-Phasen“ vier Schritte. Sie laufen nacheinander in der Reihenfolge getinfo, hostname, staticip, disks; die Liste folgt der Anzeige:',
    'clientphases_step1' => 'getinfo: der Client holt seine Geräteinformationen (u. a. Netzwerkkarten) per MAC vom Portal und legt sie lokal in der Registry ab; die folgenden Phasen (hostname, staticip) lesen ihre Sollwerte von dort. Deshalb muss getinfo immer zuerst laufen.',
    'clientphases_step2' => 'hostname: Ist der Rechner kein Domänenmitglied und weicht sein Name vom eingefrorenen Rolloutnamen ab, wird er umbenannt. Ein möglicher Abschluss-Berichtsversuch liegt vor dem geplanten Neustart; ohne Report-MAC findet dieser Versuch nicht statt. Ein Domänenmitglied wird übersprungen; ein bereits passender Name braucht keinen Neustart. Der Name wird vorher auf gültige NetBIOS-Zeichen (Buchstaben, Ziffern, Bindestrich) und höchstens :max Zeichen gekürzt; das Detail der Meldung zeigt dann „bereinigt aus …“ mit dem Sollnamen. Ein Name ohne gültiges Zeichen endet als Fehler.',
    'clientphases_step3' => 'staticip: Das Skript ändert im Windows-Gast Adaptername, DHCP oder statische IPv4-Adresse, DNS und Route auf die Zielkonfiguration. Es verschiebt die virtuelle Netzwerkkarte nicht in eine andere ESXi-Portgruppe; eine neue IP- oder Subnetzkonfiguration kann die Portalverbindung trotzdem unterbrechen. Der Adaptername wird auf den Namen der Portgruppe der Netzwerkkarte gesetzt; zu jeder konfigurierten MAC-Adresse muss im Gast ein aktiver Adapter vorhanden sein, sonst endet die Phase als Fehler.',
    'clientphases_step4' => 'disks: Vorhandene Datenträger werden nur online geschaltet und nie formatiert. Neue Offline-RAW-Datenträger werden erst nach einem dauerhaften Eigentumsbeleg als GPT mit einer NTFS-Partition über den ganzen Datenträger eingerichtet, nach dem Namen des Datenträgers auf der Seite „VM bearbeiten“ benannt und nach einem Abbruch sicher fortgesetzt. Ein unbekannter online-RAW-Datenträger oder eine offene, nicht eindeutig zuordenbare Operation ist ein Fehler; nur eine VM ohne weiteren Datenträger ist ein optionaler Erfolgsfall.',
    'clientphases_p2' => 'Phasenmeldungen sind best-effort-Telemetrie mit einem Sendeversuch. Je nach Kontrollpfad kann „gestartet“, ein terminales Ereignis oder beides fehlen. „Ausgeführt, Bestätigung ausstehend“ bedeutet nur, dass ein Start ankam und seit :minutes Minuten kein Abschluss im Portal steht; es ist weder Erfolgs- noch Fehlerbeleg. Bei vorhandener Report-MAC versucht die Hostnamephase ihren Abschluss vor einem geplanten Neustart zu melden. Bei staticip kann die neue IP- oder Subnetzkonfiguration die Zustellung unterbrechen.',
    'clientphases_p3' => 'Ein sichtbares „Fehlgeschlagen“ mit Detail belegt eine gemeldete Störung. Fehlende oder stehen gebliebene Telemetrie schließt einen echten Clientfehler nicht aus. Deshalb die Erkennungsregel der MECM-{mecm:application}, Erreichbarkeit und das lokale Skriptprotokoll auf der betroffenen VM unter C:\\Program Files\\VirtuSphere\\Logs gemeinsam prüfen.',
    'clientphases_p4' => 'Die PowerShell-Skripte auf MECM-Server und Windows-Clients schreiben dort Tagesdateien „yyyy-MM-dd_<komponente>.log“ mit sechs Feldern: ISO-8601-Zeit, Level, Komponente, Kontext, Nachricht und Korrelations-ID. Eine Nachricht ist auf :message_bytes Byte, die ganze Zeile auf :line_bytes Byte begrenzt; Unicode bleibt vollständig. Terminalformatierung wird vor der Redigierung entfernt, damit sie bekannte benannte Secret-Schlüssel nicht aufteilen kann. Unbeschriftete Geheimnisse in beliebigem Freitext kann die Redigierung nicht zuverlässig erkennen. Dateien bleiben :days Tage.',
    'clientphases_p4_b' => 'Die Korrelations-ID wird einmal pro Prozesslauf erzeugt und als reiner Diagnoseheader an das Portal mitgegeben, sie authentisiert nichts. Ist das lokale Dateilog gestört, läuft die eigentliche Aufgabe weiter und warnt pro Störung höchstens einmal lokal sowie einmal bei Erholung. Daraus entstehen weder zusätzliche Lebenszeichen noch Audit-Einträge.',
    'esxi_inv_heading' => 'ESXi-Inventar',
    'esxi_inv_p1' => 'Das Portal liest read-only in regelmäßigen Abständen aus den registrierten ESXi-Zugangsdaten: Datacenter, Datastores, Portgruppen und Host-Kapazität. Die Werte sind Snapshots vom letzten Abruf, kein Live-Monitoring. Der Abruf-Rhythmus wird in den Einstellungen gesetzt (Standard :hours Stunden); ein manueller Refresh und ein Sofort-Abruf nach dem Anlegen eines Zugangsdatums sind ebenfalls möglich.',
    'esxi_inv_p2' => 'Ist ein Abruf fehlgeschlagen, erscheint eine Fehlerkategorie (nicht erreichbar, Fehlerantwort des Hosts, Anmeldung, Berechtigungen, Ansible-Host, Auswertung). Nach einer Fehlerantwort des Hosts folgt bei eingeschalteter Automatik nach wenigen Minuten genau ein weiterer Abruf. Nur eine abgelehnte Anmeldung am ESXi-Host oder vCenter pausiert den automatischen Abruf bis zur Änderung des Zugangsdatums (Schutz vor Kontosperren). Eine abgelehnte Anmeldung am Ansible-Host pausiert ihn nicht: dort liegt kein ESXi-Konto, das gesperrt werden könnte. Der Cache bleibt bei Fehlern erhalten; nichts wird gelöscht.',
    'esxi_inv_cadence' => 'Unter jeder Inventarkarte steht der Aktualisierungspfad getrennt: Planung durch den Wartungsdienst, vorhandener Queue- oder Laufauftrag, Auftragsannahme, Bereitstellungsdienst, Ansible-Zuordnung und der Zustand „Anmeldung pausiert“ des einzelnen Zugangs. Bei pausierter Auftragsannahme kann ein Abruf bereits eingereiht sein und wartet dann auf Fortsetzung. Ein manueller Einzelabruf bleibt verfügbar.',
    'esxi_inv_rights_heading' => 'Benötigte ESXi-Rechte',
    'esxi_inv_rights_read' => 'Inventar (read-only): Lesezugriff auf Datacenter, Datastores, Netzwerk/Portgruppen und Host-Objekte.',
    'esxi_inv_rights_deploy' => 'Bereitstellung (Playbooks): VM anlegen, Datastore belegen, Netzwerk zuweisen, Power-Operationen sowie Disk-/NIC-Konfiguration.',
    'esxi_inv_p3' => 'Reicht ein Recht nicht, erscheint die Kategorie „unzureichende Berechtigungen“; dann die ESXi-Rolle des Kontos erweitern. Details stehen im Projektordner auf dem Server (nicht im Portal erreichbar): docs/operations/esxi-inventory.md.',
    'esxi_inv_deviation' => 'Der Abschnitt „Abweichungen“ vergleicht jede Objektart nur mit qualifiziertem exaktem Namensbeleg aller konfigurierten ESXi-Quellen. Aktuelle, historische und nicht auswertbare Arten bleiben verschieden; ein fehlender Beleg erzeugt weder Treffer noch Freigabe. Grün „Keine Abweichungen“ steht deshalb nur, wenn alle Arten mit aktuellem Beleg verglichen wurden; sonst zeigen Karte und Abschnitt grau „Keine Treffer, Beleg unvollständig“.',
    'esxi_inv_deviation_b' => 'Vorlagen und VMs lassen sich filtern, große Ergebnisse werden seitenweise dargestellt, die Gesamtzahl bleibt sichtbar. Die Neuzuweisung der Portgruppen zeigt vor dem Schreiben den vollständigen exakten Scope samt Konfliktaufträgen und verlangt nach jeder Änderung eine neue Vorschau. Sie ändert ausschließlich Portal-Datensätze.',
    'esxi_inv_exact_names' => 'Inventarnamen werden genau so gespeichert und verglichen, wie ESXi sie meldet. Groß- und Kleinschreibung, innere Leerzeichen und Unicode-Zeichen bleiben erhalten. Der Systemstatus zeigt nicht unterstützte Rohwerte zur Diagnose, verwendet sie aber weder als Auswahl noch als Beleg für Datacenter, Datastore, Portgruppe oder freien Speicher.',
    'esxi_inv_name_evidence' => 'Für jedes Inventarkind stehen letzter positiver Namensbeleg und letzter Abrufversuch getrennt. Ein späterer Fehler löscht den früheren Beleg nicht und macht ihn nicht aktuell. Ein leeres Missions-Datacenter wird nur aus genau einem unterstützten Datacenternamen mit Semantik 2 abgeleitet, dessen positiver Beleg höchstens :hours Stunden alt ist; die Grenze zählt einschließlich.',
    'esxi_inv_refresh_pause' => 'Der Knopf „Alle aktualisieren“ überspringt pausierte Zugangsdaten (Schutz vor Kontosperren) und weist im Hinweis darauf hin. Ein pausiertes Zugangsdatum lässt sich gezielt über „Inventarabruf starten“ an seiner Karte erneut versuchen oder durch Speichern der Zugangsdaten wieder aktivieren.',
    'esxi_inv_ampel_heading' => 'Ampel des Inventarabrufs',
    'esxi_inv_ampel_p1' => 'Die Ampel zeigt nur die Gesundheit des Abrufs. Rot: Anmeldung pausiert oder mindestens :streak Fehlversuche in Folge. Gelb: letzter Abruf fehlgeschlagen oder noch nie erfolgreich. Grau „Veraltet“: der letzte Erfolg ist älter als das :factor-fache des Intervalls; bei Intervall 0 gilt die feste Frist von :days Tagen. Grün: letzter Abruf erfolgreich und aktuell. Alte oder ungültige Zeitstempel belegen keine aktuellen Host-Eigenschaften. Host-Eigenschaften wie kostenlose Lizenz oder HA-Cluster erscheinen als eigene Badges. Dieselbe Ampel steht bei den Zugangsdaten und als Hypervisor-Kachel auf dem Dashboard.',
    'esxi_inv_catalog_heading' => 'Portgruppen-Katalog: Präsenz und VLAN-ID',
    'esxi_inv_catalog_presence' => 'Die Spalte „Auf ESXi“ zeigt, auf wie vielen erfolgreich abgerufenen Hosts eine Portgruppe existiert. Teilpräsenz (etwa auf 3 von 7 Hosts) ist gelb markiert und nennt die fehlenden Hosts: eine Bereitstellung auf einen dieser Hosts würde die Portgruppe nicht finden.',
    'esxi_inv_catalog_vlanid' => 'Die Spalte „VLAN-ID“ vergleicht die IDs gleichnamiger Portgruppen über die Hosts. Unterschiedliche IDs sind rot markiert, denn gleicher Name mit anderer ID bedeutet ein anderes Netz. Trunks/Bereiche werden nicht verglichen; ältere Abrufe ohne ID-Daten zeigen einen Platzhalter bis zum nächsten Abruf.',
    'esxi_inv_templates' => 'Der Abweichungsbericht zeigt auch Vorlagen (gekennzeichnet als „Vorlage“): eine veraltete Portgruppe, die nur noch in einer Vorlage steckt, würde sonst unbemerkt in jede daraus erzeugte Mission wandern. Ein Klick auf einen Abweichungswert einer Portgruppe befüllt die Massen-Neuzuweisung vor.',
    'esxi_test_heading' => 'Zugangsdaten testen',
    'esxi_test_p1' => 'Das Portal spricht ESXi nie direkt an. Die Aktion „Inventarabruf starten“ auf der Seite Zugangsdaten reiht für ein ESXi-Konto denselben read-only Abruf ein, den auch das Speichern auslöst: über den Ansible-Host, also genau den Weg, den eine Bereitstellung nimmt. Die Meldung bestätigt zunächst nur Warteschlange oder offenen Auftrag.',
    'esxi_test_p2' => 'Das Ergebnis steht danach dauerhaft als Ampel auf dieser Seite, nicht als einmalige Meldung. Ein Klick auf die Status-Marke unter Zugangsdaten springt zum genauen Eintrag, hebt ihn hervor und lässt ihn vollständig unter der festen Kopfzeile sichtbar. Eingereihte und laufende Aufträge sind dort ebenso direkt mit ihrem Auftragsprotokoll verlinkt wie der letzte beendete Abruf, auch nach einem Erfolg, damit sich Teilabfragen prüfen lassen. Nach Ablauf der Aufbewahrung erscheint bei einem alten Fehler ein Hinweis statt eines toten Links; ein neuer Abruf erzeugt ein neues Protokoll.',
    'esxi_test_ansible_heading' => 'Ansible-Zugang: was der Test prüft',
    'esxi_test_ansible_p1' => 'Ein Ansible-Zugang wird sofort und vollständig geprüft. Zuerst muss die lokale Ansible-Quelle mit ihrer requirements.yml lesbar sein und den vollständigen direkten und transitiven Collection-Lock tragen; ein Fehler hier ist eine lokale Konfigurationsursache und öffnet keine SSH- oder SFTP-Verbindung. Danach folgen SSH-Anmeldung, die Toolchain auf dem Host (ansible-playbook, python3, die Python-Module pyvmomi und requests sowie alle exakt festgelegten Collections), ein echter SFTP-Schreibtest in /tmp und, sofern eine API-Basis-URL gesetzt ist, ob der Host das Portal erreicht (health.php) und ob seine IP in den Machine-API IP-Freigaben steht.',
    'esxi_test_ansible_p1_b' => 'Fehlt die Freigabe, ist das Ergebnis eine Warnung, kein Fehlschlag: der Zugang funktioniert, aber Aufträge mit MAC-Export werden vor jeder VM-Änderung abgewiesen, weil ihr MAC-Upload abgelehnt würde. Schlägt etwas fehl, nennt die Meldung die betroffene Komponente statt nur eines Exit-Codes; die Rohausgabe steht hinter „Technische Details“.',
    'esxi_test_ansible_p1_c' => 'Ein bestandener Test entfernt außerdem liegengebliebene ESXi-Zugangsdateien dieses Ziels, solange der Zugang noch darauf zeigt. Das ändert die Ampel nicht; bricht das Aufräumen ab, bleibt der Rest für den nächsten Kontakt.',
    'esxi_test_ansible_p2' => 'Das Ergebnis bleibt als Status-Marke mit Zeitpunkt sichtbar. Es gilt nur für die getestete Konfigurationsrevision und neueste Testgeneration; parallele Änderungen oder neuere Tests verhindern, dass ein später eintreffender Altstand den aktuellen Zugang grün setzt. Der Volltest läuft manuell oder nach dem konfigurierten Zeitplan automatisch. Nach Ablauf der Frist oder bei ungültiger Zuordnung fehlt ein aktueller Beleg, und der Test muss wiederholt werden.',
    'esxi_test_ansible_p3' => 'Getrennt daneben steht der letzte Missionsauftrag, den der Bereitstellungsdienst tatsächlich bearbeitet hat, mit Ausgang, Zeit, Mission und, sofern berechtigt, direktem Auftragsprotokoll. Ein Auftrag, der vor dem Start aus der Warteschlange abgebrochen wurde, erscheint dort nicht: er wurde nie ausgeführt.',
    'esxi_test_ansible_p3_b' => 'Diese Zeile ist kein Volltest und beeinflusst die Volltest-Ampel nicht. Sie zeigt nur, wie weit dieser eine Auftrag kam; ein Start- oder Shutdown-Auftrag prüft beispielsweise nicht zwingend den MAC-Rückkanal. Wird der Zugang bearbeitet, verwirft das Portal deshalb weiterhin das Volltestergebnis und die Marke steht auf „Keine Daten“. Nach jeder Änderung ist ein neuer Volltest fällig; bei Bedarf sofort manuell starten.',
    'esxi_cap_heading' => 'Hinweise zum Host lesen',
    'esxi_cap_p1' => 'Nach einem erfolgreichen Abruf zeigt das Portal, was der Host ist (Produkt, Version, Lizenz, direkt oder über vCenter) und was er gerade tut. Diese Hinweise besagen nicht, dass etwas kaputt ist, sondern was der Host kann:',
    'esxi_cap_unknown' => 'Ist eine Angabe unbekannt, erscheint gar kein Hinweis. Sie wird nie als „ist in Ordnung“ gelesen. Ein Auftrag wird nur abgelehnt, wenn die Angabe aus einem frischen erfolgreichen Abruf stammt; veraltete Angaben warnen nur und lassen den Auftrag laufen.',
    'esxi_inv_host_facts' => 'Unter „Inventardetails öffnen“ nennt jede Host-Zeile zusätzlich die Kernanzahl. Weicht die Uhr des Hosts zum Zeitpunkt des Abrufs um mehr als :minutes Minuten von der Portal-Zeit ab, steht dort eine Warnung: eine stark verstellte ESXi-Uhr kann den Domänenbeitritt frisch erzeugter VMs brechen (Kerberos toleriert nur wenige Minuten). Behoben wird das per NTP auf dem ESXi-Host, nicht im Portal.',
    'esxi_cause_heading' => 'Ursachen eines fehlgeschlagenen Abrufs',
    'esxi_cause_p1' => 'Schlägt ein Abruf fehl, ordnet das Portal die Ursache einer festen Kategorie zu. Kategorie und Satz sind für jeden Betrachter sichtbar. Der Link in das Auftragsprotokoll mit dem technischen Originaltext hat dagegen zwei Bedingungen: Der Auftrag muss noch aufbewahrt sein, und die eigene Rolle muss Bereitstellungsaufträge einreihen und deren Protokolle einsehen dürfen. Ohne dieses Recht erscheint kein Link; nach der Aufbewahrungsfrist steht statt eines toten Links der Hinweis, einen neuen Abruf zu starten. Nennt die Kategorie den Ansible-Host, führt „Ansible-Status öffnen“ zum Abschnitt Ansible-Host derselben Seite.',
    'esxi_cause_th_cause' => 'Kategorie',
    'esxi_cause_th_meaning' => 'Bedeutung',
    'esxi_cause_th_fix' => 'Abhilfe',
    'esxi_cause_host_placeholder' => 'dem Host',
    'esxi_cause_fix_dns' => 'Hostnamen im Zugangsdatum prüfen, dazu DNS und Suchdomäne des Portal-Containers.',
    'esxi_cause_fix_unreachable' => 'Netzwerk, Firewall und Port prüfen. Der Abruf wird beim nächsten Intervall automatisch wiederholt; der alte Bestand bleibt erhalten.',
    'esxi_cause_fix_host_error' => 'Meist ein kurzer Aussetzer des ESXi-Verwaltungsdienstes. Ist die Automatik an, folgt nach wenigen Minuten genau ein weiterer Abruf; scheitert auch er, gilt wieder das Intervall. Bleibt der Fehler, auf dem Host den Verwaltungsdienst (hostd) und seinen Speicher prüfen. Der alte Bestand bleibt erhalten, der Zugang pausiert nicht.',
    'esxi_cause_fix_certificate' => 'In den Zugangsdaten das CA-Bundle oder Serverzertifikat und den ESXi-Hostnamen prüfen und den Zugang speichern; das startet den Test neu. Soll der Zugang ohne Prüfung laufen, dort „Ohne Zertifikatsprüfung“ wählen.',
    'esxi_cause_fix_tls' => 'TLS-Version, HTTPS-Port und Gegenstelle prüfen. Zertifikatsfehler erscheinen getrennt als certificate.',
    'esxi_cause_fix_auth' => 'Benutzername und Passwort korrigieren. Der automatische Abruf pausiert bis zur Änderung, damit das ESXi-Konto nicht gesperrt wird.',
    'esxi_cause_fix_authz' => 'Die Rolle des ESXi-Kontos erweitern. Für das Inventar genügen Leserechte, für Bereitstellen und Autostart nicht.',
    'esxi_cause_fix_ansible_dns' => 'Ansible-Hostname sowie DNS und Suchdomäne des Portal-Containers prüfen. Der ESXi-Hostname ist davon nicht betroffen.',
    'esxi_cause_fix_ansible_unreachable' => 'Netzwerk, Firewall und SSH-Port zwischen Portal und Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_auth' => 'Benutzername, Passwort, SSH-Anmeldeverfahren und Kontostatus des Ansible-Zugangs prüfen; der Host hat die Anmeldung abgelehnt, welche der vier Ursachen es war, sagt er nicht. Der ESXi-Zugang wird dadurch nicht pausiert.',
    'esxi_cause_fix_ansible_authz' => 'Rechte der Ansible-Sitzung, die SSH-/SFTP-Policy des Hosts und die betroffene entfernte Aktion prüfen. Der ESXi-Zugang wird dadurch nicht pausiert.',
    'esxi_cause_fix_ansible_preflight' => 'Im Auftragsprotokoll die fehlgeschlagene Toolchain-Komponente nachsehen und den Ansible-Host vervollständigen.',
    'esxi_cause_fix_ansible_config' => 'Playbook, Modul, Collection, Python-Abhängigkeiten, Rechteerhöhung (become) und Ansible-Ausführungsumgebung auf dem Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_sftp' => 'SFTP-Subsystem, Zielpfad, Schreibrechte, freien Speicher und Dateiübertragung auf dem Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_timeout' => 'Auftragsprotokoll und Ansible-Host auf einen stillstehenden SSH- oder SFTP-Schritt prüfen; dies ist ein VirtuSphere-Zeitbudget, kein ESXi-Timeout. Beim lesenden Inventarabruf kommen dafür ein ausgelasteter Ansible-Host, eine stockende SFTP-Übertragung, eine langsame ESXi- oder vCenter-Abfrage und ein großer Objektbestand in Frage.',
    'esxi_cause_fix_ansible_transport' => 'Auftragsprotokoll sowie SSH-Dienst und Transportweg zum Ansible-Host prüfen.',
    'esxi_cause_fix_ansible_host_identity' => 'In Zugangsdaten den beobachteten Host-Schlüssel unabhängig am Ansible-Host vergleichen und ausdrücklich bestätigen. Bei einer Abweichung bleibt die Anmeldung gesperrt; der ESXi-Zugang pausiert nicht.',
    'esxi_cause_fix_http' => 'Nur lesbarer Legacy-Wert. Erscheint er an einem alten Datensatz, ordnet ein neuer Abruf die Ursache mit dem aktuellen Vokabular ein.',
    'esxi_cause_fix_ssh' => 'Nur lesbarer Legacy-Wert ohne Verursacher. Das Auftragsprotokoll des Abrufs nennt die tatsächliche Ursache; ein neuer Abruf ersetzt den Wert durch eine Kategorie, die den Verursacher benennt.',
    'esxi_cause_fix_worker' => 'Bereitstellungsdienst, Datenbankverbindung und Auftragsprotokoll prüfen; die Kategorie behauptet keine Transportursache.',
    'esxi_cause_fix_parse' => 'Auftragsprotokoll auf fehlenden Marker, unerwartete Ausgabe oder einen verletzten Ergebnisvertrag prüfen.',
    'esxi_cause_fix_config' => 'Portal- und Auftragskonfiguration sowie den wirksamen Ansible-Quellpfad und dessen requirements.yml prüfen. Dieser Code gilt vor dem entfernten Lauf; Ansible-seitige Voraussetzungen haben eine eigene Kategorie.',
    'esxi_inv_zero_heading' => 'Grüner Abruf, trotzdem eine 0',
    'esxi_inv_zero_p1' => 'Ein Abruf besteht aus getrennten Abfragen. Eine autoritative, mit qualifizierter Semantik leere Antwort ersetzt den bisherigen Stand dieser Art durch eine bestätigte leere Menge. Abgelehnte oder übersprungene Abfragen belegen keinen leeren Bestand und erhalten den früheren Stand. Die Abrufampel bewertet den Lauf; der Abweichungsbericht bewertet die Belege je Objektart separat.',
    'esxi_inv_zero_p2' => 'Entscheidend ist, worauf das Zugangsdatum zeigt. Standard-Portgruppen und Host-Daten liest das Portal am ESXi-Host selbst; zeigt das Zugangsdatum auf ein vCenter, bleiben genau diese beiden leer, während Datacenter und Datastores ankommen. Distributed-Portgruppen gibt es umgekehrt nur unter vCenter: an einem einzelnen ESXi-Host ist ihre 0 der Normalfall. Für ein vollständiges Inventar ist ein Zugangsdatum auf den ESXi-Host der geprüfte Weg.',
    'esxi_inv_zero_p3' => 'Raten muss dafür niemand: jeder Abruf protokolliert selbst, welche seiner Abfragen geantwortet hat. Im Auftragsprotokoll steht direkt unter den Zahlen die Zeile „Inventory queries“.',
    'esxi_inv_zero_p3_b' => 'Entweder meldet sie, dass alle Abfragen geantwortet haben („all … answered“), dann sind alle Zahlen belastbar und eine 0 ist eine echte 0. Oder sie nennt jede stumme Abfrage mit einem von zwei Wörtern: „rejected“ heißt, die Abfrage wurde abgelehnt, oft bevor sie ESXi überhaupt erreicht hat, und die Meldung dahinter stammt wörtlich vom Modul; „skipped“ heißt, das Playbook hatte nichts zu fragen, etwa Distributed-Portgruppen ohne bekanntes Datacenter. Scheitern mehrere Abfragen an derselben Ursache, werden sie gemeinsam vor einer Meldung genannt.',
    'esxi_inv_zero_p4' => 'Eine bestätigte leere Antwort ist selbst ein Ergebnis und leert den Cache dieser Art; der Katalog „Portgruppen“ kann eine belegt nicht mehr gemeldete Portgruppe zurückziehen. Nur rejected, skipped und fehlende Semantik erhalten Altbestand, ohne ihn aktuell zu machen. Fehlt die Zeile „Inventory queries“ ganz, stammt der Abruf aus einem älteren Stand ohne Beleg für Vollständigkeit; dann hilft ein neuer Abruf.',
    'esxi_inv_zero_p5' => 'Direkt darunter steht die Zeile „Datastore health“. Sie nennt, für wie viele Datastores der Abruf Erreichbarkeit und Wartungsmodus überhaupt mitgeliefert hat, und danach namentlich die, die im Wartungsmodus oder nicht erreichbar sind. Auch der gute Fall steht dort, aus demselben Grund wie bei den Abfragen: eine Flotte ohne Wartung und ein Feld, das der Abruf gar nicht mehr trifft, sähen sonst gleich aus. Ein Datastore im Wartungsmodus wird in den Auswahllisten gekennzeichnet, und sein freier Speicher gilt überall als unbekannt statt als verfügbar.',
    // PR-R4B: der Rest des gekürzten Befunds package_config_invalid.
    'system_status_status_config_values' => 'Erlaubte Werte in der config.json eines Pakets: ProjectName und version sind nichtleere Zeichenketten ohne Leerraum am Rand und ohne *, ?, [ oder ]; Bindestriche sind in ProjectName erlaubt, in version weder Bindestrich noch Leerraum. Numerische Versionen wie 0.2 sind eindeutig vergleichbar, und eine geänderte Version kann eine neue {mecm:application} erzeugen. ErrorAction ist Stop oder Continue, InstallationBehaviorType ist leer, InstallForSystem oder InstallForUser. DeployTo ist leer oder genau der Name einer {mecm:collection} ohne Leerraum am Rand und ohne *, ?, [ oder ].',
];
